import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    rows = data[2:2 + n]
    name = {}
    ch = {}
    roots = []
    for r in rows:
        a, p, nm = r.split(',')
        i = int(a)
        name[i] = nm
        ch.setdefault(i, [])
        if p == 'null':
            roots.append(i)
        else:
            ch.setdefault(int(p), []).append(i)
    def expand(lst):
        seq = ['[']
        for k, c in enumerate(lst):
            if k:
                seq.append(',')
            seq.append(c)
        seq.append(']')
        return seq
    stack = list(reversed(expand(roots)))
    out = []
    while stack:
        t = stack.pop()
        if isinstance(t, int):
            stack.append('}')
            stack.extend(reversed(expand(ch[t])))
            stack.append('{"id":%d,"name":"%s","children":' % (t, name[t]))
        else:
            out.append(t)
    print(''.join(out))

main()

